    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    max_gap = 6

    def fill_line(values, coords):
        # Locate each contiguous non-background run in the 1-D sequence, then fill
        # all blank intervals between the first and last anchor, up to max_gap.
        anchors = [i for i, value in enumerate(values) if value != bg]
        if len(anchors) < 2:
            return
        for a, b in zip(anchors, anchors[1:]):
