 "content": "def transform(grid):
    """Bridge short gaps on rows/columns containing multiple foreground markers."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)
    out = [row[:] for row in grid]
    max_empty_gap = 6

    # On an active line (two or more markers), fill short empty intervals,
    # including a short interval from an outer marker to the object's bbox edge.
    for r in range(rmin, rmax + 1):
        anchors = [c for c in range(cmin, cmax + 1) if grid[r][c] != background]
        if len(anchors) < 2:
            continue
        intervals = [(cmin, anchors[0])] + list(zip(anchors, anchors[1:])) + [(anchors[-1], cmax)]
        for a, b in intervals:
            if b - a - 1 <= max_empty_gap:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    for c in range(cmin, cmax + 1):
        anchors = [r for r in range(rmin, rmax + 1) if grid[r][c] != background]
        if len(anchors) < 2:
            continue
        intervals = [(rmin, anchors[0])] + list(zip(anchors, anchors[1:])) + [(anchors[-1], rmax)]
        for a, b in intervals:
            if b - a - 1 <= max_empty_gap:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out
